CREATE TABLE IF NOT EXISTS lead_scoring_rules(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name TEXT NOT NULL,field TEXT NOT NULL,operator TEXT NOT NULL CHECK(operator IN ('equals','contains','exists')),value TEXT,points INTEGER NOT NULL,reason TEXT,priority INTEGER NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX IF NOT EXISTS lead_rules_tenant_idx ON lead_scoring_rules(tenant_id,is_active,priority);